/* ---------------- layout ---------------- */
function exLayout(n) {
  if (n.custom === 'nn') { const L = n.kids.filter(x => x.fx === 'neurons'), O = n.kids.filter(x => x.fx !== 'neurons'), cell = [1.7, 1.2, 1.0], out = []; n.kids.forEach(ch => { const isL = ch.fx === 'neurons', arr = isL ? L : O, i = arr.indexOf(ch); out.push({ node: ch, pos: [(i - (arr.length - 1) / 2) * (isL ? 2.5 : 2.6), isL ? 0 : -2.6, 0], size: isL ? [1.2, 1.2, 1.7] : cell }); }); return { items: out, ext: [Math.max(.5, ...out.map(o => Math.abs(o.pos[0]) + o.size[0] / 2)), Math.max(.5, ...out.map(o => Math.abs(o.pos[1]) + o.size[1] / 2)), 1.5] }; }
  const k = n.kids, c = k.length, lay = n.layout || (n.flow ? 'row' : (c > 6 ? 'grid' : 'row')), gap = 1.0, cell = [1.7, 1.2, 1.0], out = [];
  k.forEach((ch, i) => {
    let p;
    if (lay === 'row') { const rows = c > 8 ? 3 : c > 5 ? 2 : 1, per = Math.ceil(c / rows), r = Math.floor(i / per), ci = i % per, inRow = Math.min(per, c - r * per); p = [(ci - (inRow - 1) / 2) * (cell[0] + gap), ((rows - 1) / 2 - r) * (cell[1] + gap * 1.1), 0]; }
    else if (lay === 'stack') p = [0, 0, ((c - 1) / 2 - i) * (cell[2] + .55)];
    else if (lay === 'ring') { const a = i / c * 6.2832; p = [Math.cos(a) * (1.3 + c * .35), Math.sin(a) * (1.3 + c * .35), 0]; }
    else { const cols = Math.ceil(Math.sqrt(c)), rows = Math.ceil(c / cols), ci = i % cols, ri = Math.floor(i / cols); p = [(ci - (cols - 1) / 2) * (cell[0] + gap * .6), 0, ((rows - 1) / 2 - ri) * (cell[2] + gap * .8)]; }
    out.push({ node: ch, pos: p, size: cell });
  });
  const ext = [0, 1, 2].map(a => Math.max(.5, ...out.map(o => Math.abs(o.pos[a]) + o.size[a] / 2)));
  return { items: out, ext };
}

