    const e2 = (d, lab, mx, my, back) => { s += `<path class="exe" d="${d}" stroke="var(--muted)" stroke-width="1.7" ${back ? 'stroke-dasharray="5 4"' : ''} marker-end="url(#exa)" fill="none"/>`; if (lab) s += `<text x="${mx}" y="${my}" text-anchor="middle" class="tk" style="paint-order:stroke;stroke:var(--surface2);stroke-width:4px">${esc(lab)}</text>`; };
    edges.forEach(([i, j, lab, back]) => { const a = dpos[i], b = dpos[j]; if (!a || !b) return; let d, mx, my;
      if (back) { d = `M${a[0]} ${a[1] + a[3] / 2}C${a[0]} ${H - 4} ${b[0]} ${H - 4} ${b[0]} ${b[1] + b[3] / 2 + 3}`; mx = W / 2; my = H - 10; }
      else if (Math.abs(a[1] - b[1]) < 5) { d = `M${a[0] + a[2] / 2} ${a[1]}L${b[0] - b[2] / 2 - 3} ${b[1]}`; mx = (a[0] + b[0]) / 2; my = a[1] - 7; if (Math.abs(b[0] - a[0]) - a[2] < 40) lab = ''; }
      else { d = `M${a[0]} ${a[1] + a[3] / 2}C${a[0]} ${a[1] + a[3]} ${b[0]} ${b[1] - b[3]} ${b[0]} ${b[1] - b[3] / 2 - 3}`; mx = (a[0] + b[0]) / 2; my = (a[1] + b[1]) / 2; }
      e2(d, lab, mx, my, back); });
    k.forEach((ch, i) => { if (!dpos[i]) return; const [x, y, w, hh] = dpos[i], on = st.sel === ch, col = colOf(ch, i), sub = (ch.text || '').replace(/<[^>]+>/g, '').split(/[.:]/)[0];
      s += `<g class="exb${on ? ' on' : ''}" data-i="${i}" style="cursor:pointer">${glyph(ch, x, y, w, hh, col, on)}<text x="${x}" y="${y - 3}" text-anchor="middle" class="al" style="font-size:${w < 112 ? 10.5 : 12.5}px">${esc(ch.name.length > Math.floor(w / 6.3) ? ch.name.slice(0, Math.floor(w / 6.3) - 1) + '…' : ch.name)}</text>${w >= 112 ? `<text x="${x}" y="${y + 12}" text-anchor="middle" class="tk">${esc(sub.length > w / 7.4 ? sub.slice(0, Math.floor(w / 7.4) - 1) + '…' : sub)}</text>` : ''}${ch.kids.length ? `<text x="${x + w / 2 - 6}" y="${y - hh / 2 - 4}" text-anchor="end" class="tk" style="fill:${col}">${ch.kids.length} parts ▸</text>` : ''}</g>`; });
